import{_ as e,c as l,o as t,a8 as r}from"./chunks/framework.jsZJWZJf.js";const p=JSON.parse('{"title":"《明朝那些事儿》","description":"","frontmatter":{},"headers":[],"relativePath":"blog/read/读后感/20230804明朝那些事儿.md","filePath":"blog/read/读后感/20230804明朝那些事儿.md","lastUpdated":1795103431000}'),i={name:"blog/read/读后感/20230804明朝那些事儿.md"};function _(o,a,d,n,s,c){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="《明朝那些事儿》" tabindex="-1">《明朝那些事儿》 <a class="header-anchor" href="#《明朝那些事儿》" aria-label="Permalink to “《明朝那些事儿》”">​</a></h1><h2 id="_2023-08-04-09-21-周五" tabindex="-1">2023-08-04 09:21 周五 <a class="header-anchor" href="#_2023-08-04-09-21-周五" aria-label="Permalink to “2023-08-04 09:21 周五”">​</a></h2><ul><li>终于把明朝那些事儿看完了，其实最后作者为了避免结局太过悲伤，很多细节都省略了，只写了崇祯自尽，砍了女儿的手臂，就草草结束，并没有详细写很多，明朝那些大臣们如何处置，李自成跟清军是否又发生过战乱，这类的事情…</li><li>对于我来说再悲哀的结局也好，还是更想看到一个完整的结局</li><li>这个故事实在太长了，中间穿插的人物很多，很杂，不过我也按照自己的想法整理了一些故事梗概，也是顺便帮自己梳理一下，也是希望可以锻炼我自己读书的能力，跳出故事本身，去理解作者想要表达什么，传递什么，以自己的方式来梳理故事，理解故事。我想，我还是应该再继续多看一下豆瓣跟知乎上对这本书的评价，看看别人是如何看这本书，如何去理解故事的。</li><li>历史中的人有好有坏，其实很多也都无从考证，从书一开始作者就说了，写历史的人，也有自己的观点立场，不一定就是真实的，所以要多方考证。</li><li>看了那么多人的故事，真的就是最后作者说的，看前几十页的时候觉得这人好牛逼，可是往后看的时候，这人就开始被整或者犯错，最后悲凉结局，很是令人唏嘘。不过我觉得古代的人真的好能坚守，就算被贬了，也依旧不放弃，依然在等待，不知道什么时候就又会被召回任用，等几个月，几年，甚至十年，考取功名，可以一直考到三十多岁，三十多岁一事无成。</li><li>其实当时有好多感想真的好多好多。不过到现在都觉得在作者最后写的总结里面了。作者写的总结比我好太多了。如果我有什么感触，也会再去读一遍结尾。</li></ul>',3)])])}const m=e(i,[["render",_]]);export{p as __pageData,m as default};
